class Solution:
    def maxNumberOfBalloons(self, text: str) -> int:
        freq = [0] * 5 # unique chars in balloon

        for ch in text:
            if ch == 'a':
                freq[0] += 1
            if ch == 'b':
                freq[1] += 1
            if ch == 'l':
                freq[2] += 1
            if ch == 'o':
                freq[3] += 1
            if ch == 'n':
                freq[4] += 1

        return min([freq[0], freq[1], freq[2] // 2, freq[3] // 2, freq[4]])
